/**
 * Day 16 — String Part-II. Original statements + reference solutions for the
 * in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 */

export default {
  section: 'Day 16: String Part-II',
  problems: [
    {
      slug: 'z-function',
      title: 'Z-Function (Z-algorithm)',
      difficulty: 'Hard',
      topic: 'Strings',
      description: `For a string \`S\` of length \`n\`, the **Z-array** is defined as: \`z[i]\` = the length of the longest common prefix of \`S\` and the suffix of \`S\` starting at position \`i\` (for \`i >= 1\`). By convention here, \`z[0] = n\`.

Compute the whole Z-array.

Input format: one line containing \`S\` (at least one character).

Print \`n\` values separated by single spaces.

{{EXAMPLES}}`,
      constraints: '1 <= |S| <= 10^5\nS contains lowercase letters and digits only',
      inputs: ['aaaaa', 'ababaa', 'aabcaabxaaaz', 'a', 'abc', 'zabcabdez', '0000'],
      solve(input) {
        const s = input.trim().split('\n')[0];
        const n = s.length;
        const z = new Array(n).fill(0);
        z[0] = n;
        let l = 0, r = 0;
        for (let i = 1; i < n; i++) {
          if (i < r) z[i] = Math.min(r - i, z[i - l]);
          while (i + z[i] < n && s[z[i]] === s[i + z[i]]) z[i]++;
          if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z.join(' ');
      },
    },
    {
      slug: 'kmp-lps-array',
      title: 'KMP Algorithm — Compute the LPS (π) Array',
      difficulty: 'Hard',
      topic: 'Strings',
      description: `For a pattern \`P\` of length \`n\`, the **LPS array** (longest proper prefix which is also a suffix, also called π) is defined as: \`lps[i]\` = the length of the longest proper prefix of \`P[0..i]\` that is also a suffix of \`P[0..i]\`.

Compute the LPS array of the pattern.

Input format: one line containing the pattern (at least one character).

Print \`n\` values separated by single spaces.

{{EXAMPLES}}`,
      constraints: '1 <= |P| <= 10^5\nP contains lowercase letters and digits only',
      inputs: ['aaaa', 'ababaa', 'abcabx', 'a', 'abca', 'xyzxyzxy', '010101'],
      solve(input) {
        const p = input.trim().split('\n')[0];
        const n = p.length;
        const lps = new Array(n).fill(0);
        let len = 0;
        let i = 1;
        while (i < n) {
          if (p[i] === p[len]) { len++; lps[i] = len; i++; }
          else if (len !== 0) len = lps[len - 1];
          else { lps[i] = 0; i++; }
        }
        return lps.join(' ');
      },
    },
    {
      slug: 'minimum-characters-for-palindrome',
      title: 'Minimum Characters Added at Front to Make String Palindrome',
      difficulty: 'Hard',
      topic: 'Strings',
      description: `Given a string, find the minimum number of characters that must be added to its **front** so that the resulting string is a palindrome.

Print that minimum number of characters.

Input format: one line containing the string (at least one character).

{{EXAMPLES}}`,
      constraints: '1 <= |S| <= 10^5\nS contains lowercase letters only',
      inputs: ['a', 'aa', 'abcd', 'abcba', 'race', 'abac', 'banana'],
      solve(input) {
        const s = input.trim().split('\n')[0];
        const n = s.length;
        // longest suffix that is itself a palindrome (suffix starting at index 0
        // means the string is already a palindrome)
        for (let start = 0; start < n; start++) {
          const suffix = s.slice(start);
          if (suffix === [...suffix].reverse().join('')) return String(start);
        }
        return String(n);
      },
    },
    {
      slug: 'check-anagrams',
      title: 'Check for Anagrams',
      difficulty: 'Easy',
      topic: 'Strings',
      description: `Two strings are **anagrams** of each other if they contain exactly the same characters with the same frequencies (in any order).

Print \`YES\` if the two given strings are anagrams, otherwise \`NO\`.

Input format: first line the first string, second line the second string (both non-empty, no spaces).

{{EXAMPLES}}`,
      constraints: '1 <= length of each string <= 10^5\nBoth strings contain lowercase letters only',
      inputs: [
        'listen\nsilent',
        'rat\ncar',
        'a\na',
        'aab\nbba',
        'hello\nworld',
        'triangle\nintegral',
        'abc\nabcd',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const a = lines[0].split('').sort().join('');
        const b = lines[1].split('').sort().join('');
        return a === b ? 'YES' : 'NO';
      },
    },
    {
      slug: 'count-and-say',
      title: 'Count and Say Sequence',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `The count-and-say sequence starts with \`"1"\`. Each next term describes the previous term digit by digit: groups of identical digits become (count)(digit).

Terms: \`1\` → \`11\` → \`21\` → \`1211\` → \`111221\` → \`312211\` → ...

Given \`N\`, print the \`N\`-th term (term 1 is \`"1"\`).

Input format: one line containing \`N\`.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 30',
      inputs: ['1', '2', '4', '5', '6', '10', '12'],
      solve(input) {
        let current = '1';
        const N = Number(input.trim());
        for (let term = 1; term < N; term++) {
          let next = '';
          let i = 0;
          while (i < current.length) {
            let j = i;
            while (j < current.length && current[j] === current[i]) j++;
            next += `${j - i}${current[i]}`;
            i = j;
          }
          current = next;
        }
        return current;
      },
    },
    {
      slug: 'compare-version-numbers',
      title: 'Compare Version Numbers',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Two version strings are dot-separated lists of numeric revisions (each revision may have leading zeros, e.g. \`01\` = \`1\`).

Compare them:
- print \`1\` if version1 > version2,
- print \`-1\` if version1 < version2,
- print \`0\` if they are equal.

Missing revisions count as \`0\` (e.g. \`1.0\` == \`1.0.0\`).

Input format: first line version1, second line version2.

{{EXAMPLES}}`,
      constraints: '1 <= number of revisions <= 50\n0 <= each revision <= 10^6 (leading zeros allowed)\nEach line has at most 100 characters',
      inputs: [
        '1.01\n1.001',
        '1.0\n1.0.0',
        '0.1\n1.1',
        '1.2\n1.10',
        '7.5.2.4\n7.5.3',
        '1.0.1\n1.0.1',
        '00.00.01\n0.0.1',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const a = lines[0].split('.').map(Number);
        const b = lines[1].split('.').map(Number);
        const len = Math.max(a.length, b.length);
        for (let i = 0; i < len; i++) {
          const x = a[i] ?? 0;
          const y = b[i] ?? 0;
          if (x > y) return '1';
          if (x < y) return '-1';
        }
        return '0';
      },
    },
  ],
};
